class Solution {
public:
    long long maxScore(vector<int>& nums, int x) {
        const long long NEG = -1000000000000000000LL;
        long long dp[2];
        dp[0] = dp[1] = NEG;
        dp[nums[0] % 2] = nums[0];
        for (int i = 1; i < (int)nums.size(); i++) {
            int p = nums[i] % 2;
            long long best = max(dp[p], dp[1 - p] - (long long)x) + nums[i];
            dp[p] = max(dp[p], best);
        }
        return max(dp[0], dp[1]);
    }
};
